  "guideCordisExplanation": "โหมดครีเอเตอร์ให้เอเจนต์เขียนปลั๊กอินที่เพิ่มฟีเจอร์หรือ UI หรือรวมเครื่องมือและพรอมต์เป็นโหมดของคุณเอง",
