  "guideTitle": "ขั้นตอนการเปิดใช้",
  "step1": "ต่อมือถือกับคอมพิวเตอร์ด้วยสายข้อมูล ครั้งแรกจะเด้งถามว่า \"อนุญาต USB ดีบักไหม\" ให้ติ๊ก \"อนุญาตเสมอ\" แล้วกดตกลง",
  "step2": "เปิดเทอร์มินัลบนคอมพิวเตอร์ แล้วรันคำสั่งด้านล่าง — ให้ adbd ของมือถือฟังที่พอร์ต 5555 Android 10 ต้องทำซ้ำทุกครั้งที่รีสตาร์ทเครื่อง",
  "step3": "จากนั้นรันคำสั่งด้านล่าง เพื่ออัดคีย์ที่อนุญาตแล้วบนคอมพิวเตอร์ไปยังโฟลเดอร์ร่วมของมือถือ (macOS / Linux ให้เปลี่ยน %USERPROFILE%\\.android\\adbkey เป็น ~/.android/adbkey)",
  "step4": "กลับมาที่หน้านี้ แล้วกด \"ตรวจสอบใหม่\" ด้านบน แอปจะย้ายคีย์เข้าโฟลเดอร์ส่วนตัวของตัวเอง และลบไฟล์ชั่วคราวในโฟลเดอร์ร่วมทันที",
  "cmd2": "adb tcpip 5555",
  "cmd3": "adb push %USERPROFILE%\\.android\\adbkey /sdcard/dsh_adbkey",
  "copy": "คัดลอก",
  "copied": "คัดลอกแล้ว",
  "copyFailed": "คัดลอกไม่สำเร็จ",
  "notesTitle": "ข้อควรทราบ",
  "note1": "คีย์นี้เทียบเท่าสิทธิ์ควบคุมเครื่อง แอปเก็บไว้เฉพาะในโฟลเดอร์ส่วนตัว และลบไฟล์ชั่วคราวบน /sdcard ทันทีหลังนำเข้า",
  "note2": "ถ้าถอนแล้วติดตั้งใหม่ คีย์จะหาย ต้องทำขั้นตอนข้างบนใหม่",
  "note3": "คำสั่งที่รันด้วยสิทธิ์พิเศษจะไม่ผ่านแซนด์บ็อกซ์ — สิทธิ์นั้นอ่านโฟลเดอร์ส่วนตัวของแอปไม่ได้ และแซนด์บ็อกซ์การเขียนกับ link ทรานสเลชันก็ไม่มีผลกับมัน",
  "wlTitle": "ดีบักไร้สาย (Android 11+ ไม่ต้องใช้คอมพิวเตอร์)",
  "wlIntro": "ตั้งแต่ Android 11 ระบบมี \"ดีบักไร้สาย\" ในตัว ทำให้แอปนี้ได้สิทธิ์พิเศษเองโดยไม่ต้องใช้สายหรือคอมพิวเตอร์ และยังใช้ได้หลังรีสตาร์ทเครื่อง ครั้งแรกต้องจับคู่หนึ่งครั้ง",
  "wlStep1": "กดปุ่ม \"จับคู่ดีบักไร้สาย\" ด้านล่างในหน้านี้ — จะมีแจ้งเตือนค้างในแถบแจ้งเตือนบอกว่าต้องไปที่ไหนต่อ",
  "wlStep2": "เปิดสวิตช์ \"ดีบักไร้สาย\" ใน \"การตั้งค่า → ตัวเลือกนักพัฒนา\" ของระบบ แล้วเข้า \"จับคู่อุปกรณ์ด้วยรหัสจับคู่\"",
  "wlStep3": "เมื่อหน้านั้นเปิดขึ้น แจ้งเตือนจะเปลี่ยนเป็นช่องกรอกอัตโนมัติ (แอปนี้จะรอเรื่อย ๆ ไม่ต้องกลับมากดใหม่) ให้เลื่อนแถบแจ้งเตือนลง แล้วพิมพ์รหัสจับคู่ 6 หลักในนั้นได้เลย",
  "wlStep4": "เมื่อจับคู่สำเร็จ กลับมาที่หน้านี้แล้วกด \"ตรวจสอบใหม่\" สิทธิ์ควรเปลี่ยนเป็น uid 2000 จากนั้นจะใช้ได้ตลอด ไม่ต้องจับคู่อีก",
  "wlPair": "จับคู่ดีบักไร้สาย",
  "wlPairing": "กำลังรอ…",
  "wlPairingHint": "เริ่มรอแล้ว ไปที่ \"การตั้งค่า → ตัวเลือกนักพัฒนา → ดีบักไร้สาย\" ของระบบ แล้วเปิด \"จับคู่อุปกรณ์ด้วยรหัสจับคู่\" ค้างไว้ — แอปนี้จะรอเรื่อย ๆ (ไม่หมดเวลา) พอพอร์ตโผล่ แถบแจ้งเตือนจะกลายเป็นช่องกรอก ถ้าต้องการหยุด ให้กด \"ยกเลิกการจับคู่\" ด้านบน",
