  "disclaimer.reopen": "ข้อกำหนดและข้อจำกัดความรับผิด",
  "ann.p1": "ไม่ต้องใช้ข้อมูลรับรอง: ติดตั้งแล้วใช้ได้ — ไม่ต้องสมัคร ไม่มี API key ให้วาง",
  "ann.p2": "รายชื่อตามต้นทาง: โมเดล ความยาวบริบท และความสามารถจะถูกดึงใหม่ทุกครั้งที่รีเฟรช",
  "ann.n1": "มีโมเดลใหม่สองตัวในเลน EAC ส่งต่อจากระดับฟรีของ OpenCode: DeepSeek V4.1 Flash Free และ GLM 5.3 Flash Free",
  "ann.n2": "ทั้งคู่อยู่ต้นหน้าของหน้าโมเดล EAC ทำเครื่องหมายด้วยป้าย ใหม่ / ฮอต สีแดง และแท็ก \"เร็ว\"",
  "ann.n3": "ทั้งคู่เปิดระดับการใช้เหตุผลจริง (ต่ำ / สูง / สูงสุด) และ DeepSeek ปิดการใช้เหตุผลได้ด้วย; ระดับจะถูกส่งไปต้นทางตามจริง ไม่ใช่คำใบ้ในพรอมต์",
  "ann.s1": "เลือกโมเดลใดก็ได้ใต้กลุ่ม “Our Free Model” ในตัวเลือกโมเดลของคอมโพเซอร์",
  "ann.s4": "โมเดลที่จำกัดตามภูมิภาคจะจัดประเภทตัวเองใหม่เมื่อ egress ของเครือข่ายเปลี่ยน",
  "ann.u3": "อัปเกรดในแอป: การติดตั้งที่จัดการเองอัปเดตได้จากตั้งค่า; การติดตั้งที่โฮสต์จัดการใช้วิธีติดตั้งเดิม",
  "ann.u4": "การติดตั้งที่จัดการเองใช้การอัปเกรดในแอปและโหลดใหม่แบบร้อนได้ สำหรับการติดตั้งที่โฮสต์จัดการ ให้อัปเดตผ่านวิธีติดตั้งเดิมแล้วรีโหลดตามที่โฮสต์กำหนด",
  "section.upgradeHint": "อัปเดตตามแหล่งที่ติดตั้ง; การติดตั้งที่โฮสต์จัดการใช้วิธีติดตั้งเดิม",
  "upgrade.managed": "การติดตั้งนี้ถูกจัดการโดยโฮสต์ที่ติดตั้งมัน อัปเดตผ่านวิธีติดตั้งเดิม; การตรวจ อัปเกรด และโหลดใหม่แบบร้อนในปลั๊กอินใช้ไม่ได้",
