  "picks.sub": "ชุดโปรเจกต์โอเพนซอร์สของผู้เขียนคนเดียวกัน: พาเอเจนต์ไปสู่เดสก์ท็อปแบบเนทีฟ ทำให้ปลั๊กอินหลายร้อยตัวทำงานร่วมกัน และทำงานวิดีโอและงานออกแบบบนเครื่องนี้ หากมีประโยชน์ ดาวคือคำขอบคุณที่พวกเขาเข้าใจ",
